#!/usr/bin/env bash
# Shared helpers. Run the entrypoint scripts with bash, never with sh or bash -x.
set +x
set -Eeuo pipefail
umask 077
ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd -P)
cd "$ROOT"
# Do not allow inherited Compose profiles to start Odoo.
unset COMPOSE_PROFILES COMPOSE_FILE
SERVICES=(db api mock_erp worker caddy)
load_env() {
    [[ -f .env && ! -L .env ]] || { echo 'Missing regular .env file.' >&2; return 1; }
    [[ $(stat -c %a .env) == 600 ]] || { echo '.env must have mode 600.' >&2; return 1; }
    # .env is trusted executable shell input, generated by bootstrap and owned by the operator.
    set -a
    # shellcheck source=/dev/null
    source .env
    set +a
    unset COMPOSE_PROFILES COMPOSE_FILE
    export COMPOSE_PROJECT_NAME=order-gateway
}
compose() {
    docker compose --env-file "$ROOT/.env" -p order-gateway \
        -f "$ROOT/docker-compose.yml" -f "$ROOT/deploy/docker-compose.prod.yml" "$@"
}
check_ports() {
    # Never print full config: it contains credentials. Only expose this assertion's result.
    compose config --format json | python3 -c '
import json,sys
c=json.load(sys.stdin)
p=[(n,str(p["published"]),int(p["target"])) for n,s in c["services"].items() for p in s.get("ports",[])]
assert sorted(p)==[("caddy","443",443),("caddy","80",80)], "Unexpected published ports"
assert c["services"]["api"]["environment"]["ERP_ADAPTER"]=="mock"
assert c["services"]["worker"]["environment"]["ERP_ADAPTER"]=="mock"
assert c["services"]["db"]["volumes"][0]["type"]=="volume"
print("PASS: only Caddy publishes TCP 80 and 443; ERP is mock; database uses a named volume")'
}
wait_health() {
    compose up -d --wait --wait-timeout 180 "${SERVICES[@]}"
    echo 'PASS: all five core services are healthy'
}
